CREATE TABLE t1(rowid, oid, _rowid_, x); CREATE TABLE log(a,b,c,d,e); CREATE TRIGGER r3 BEFORE UPDATE ON t1 BEGIN INSERT INTO log VALUES('r3.old', old.rowid, old.oid, old._rowid_, old.x); INSERT INTO log VALUES('r3.new', new.rowid, new.oid, new._rowid_, new.x); END; CREATE TRIGGER r4 AFTER UPDATE ON t1 BEGIN INSERT INTO log VALUES('r4.old', old.rowid, old.oid, old._rowid_, old.x); INSERT INTO log VALUES('r4.new', new.rowid, new.oid, new._rowid_, new.x); END; INSERT INTO t1 VALUES(100,200,300,400); DELETE FROM log;